# =========================================================== 9 MASTER DATA
H1("9.  Master Data Requirements", page_break=True)
P("The integrity of the whole process rests on four master data structures: where stock is held, where it is "
  "installed, what it is, and which purchase order it came from. These must be established and approved "
  "before any transaction is permitted.", align="j")

H2("9.1  Store Location Master")
P("Stock is never held in a store as a whole. It is held at a specific, named, physical position within a "
  "store, expressed as a four-level hierarchy. This is what allows a Store Keeper to be directed to material "
  "rather than searching for it.", align="j")
TBL(["Level", "Element", "Example", "Rule"],
    [["1", "Store", "ST-CEN-01 — Central Store, Zone A", "A physical building or yard with a nominated Store In-Charge. Mandatory."],
     ["2", "Zone / Section", "ZN-LUM — Luminaires Section", "A logical partition of the store, typically by article family. Mandatory."],
     ["3", "Rack / Row", "RK-04", "Physical rack, row or stack. Mandatory for binnable articles."],
     ["4", "Bin / Shelf", "BN-12", "The lowest addressable position. Mandatory for binnable articles; optional for bulk items held in a yard."]],
    widths=[1.4, 3.4, 5.4, 5.8])

H3("Store Location Attributes")
TBL(["Attribute", "Type", "Mandatory", "Description"],
    [["Store Code", "Code", "Yes", "Unique, system-controlled, never reused"],
     ["Store Name", "Text", "Yes", "Descriptive name as used operationally"],
     ["Store Type", "List", "Yes", "Central / Zonal / Sub-store / Quarantine / Scrap yard"],
     ["Address and coordinates", "Text, lat-long", "Yes", "Used for transfer logistics and map views"],
     ["Store In-Charge", "User link", "Yes", "Accountable officer; drives approval routing"],
     ["Full location code", "Derived", "Yes", "Store-Zone-Rack-Bin, generated by the system"],
     ["Capacity / remarks", "Text", "No", "Free text for operational notes"],
     ["Status", "List", "Yes", "Active / Inactive. A location holding stock cannot be made inactive"]],
    widths=[3.6, 2.6, 2.0, 7.8])

H2("9.2  Site Location Master")
P("A site location is the physical point at which street lighting material is installed. Every site must "
  "exist in this master, with coordinates, before material can be requisitioned for it. This is the reference "
  "against which installation evidence is validated.", align="j")
TBL(["Attribute", "Type", "Mandatory", "Description"],
    [["Site Code", "Code", "Yes", "System-generated, unique and permanent, e.g. SITE-ZA-RD14-0087"],
     ["Site Name / Description", "Text", "Yes", "Road, junction, chowk, park or landmark description"],
     ["Administrative hierarchy", "List", "Yes", "Zone → Division → Sub-division → Ward or UC"],
     ["Latitude / Longitude", "Decimal", "Yes", "Captured to at least six decimal places"],
     ["Geo-fence radius", "Number (m)", "Yes", "Acceptance radius for installation evidence; defaults from configuration"],
     ["Site type", "List", "Yes", "Road stretch / Junction / Park / Public building / Pole cluster"],
     ["Pole or point identifier", "Text", "No", "Where individual poles are numbered within a site"],
     ["Assigned Lighting Supervisor", "User link", "Yes", "Controls who may requisition for this site"],
     ["Assigned Lighting Officer", "User link", "No", "Default installer for the site"],
     ["Sanctioned quantity by article", "Table", "No", "Approved scope for the site; drives over-issue warnings"],
     ["Status", "List", "Yes", "Planned / Active / Completed / On hold"]],
    widths=[4.0, 2.4, 2.0, 7.6])
P("Note: site locations may be created in bulk from a survey upload at the start of the project and "
  "individually thereafter. Creation and amendment of a site location, particularly its coordinates, is a "
  "controlled action requiring Supervisor submission and Store In-Charge or PD Office approval.",
  italic=True, size=9.5, align="j")

H2("9.3  Article and Item Code Master")
P("Articles are created article-wise with a unique item code, and each item code carries the reference of the "
  "purchase order against which it was bought. This is the single design decision that makes consumption, "
  "failure and warranty analysis possible by vendor and by PO.", align="j")

H3("Item Code Structure")
P("A structured, readable code is used so that the item can be partly identified by eye when the label is "
  "damaged. The suggested pattern is:", align="j")
P("CAT-SUBCAT-SPEC-PO-SEQ      for example      LUM-LED-090W-PO2611-000482",
  bold=True, align="c", size=11)
TBL(["Segment", "Meaning", "Example", "Source"],
    [["CAT", "Article category", "LUM (luminaire), POL (pole), CBL (cable), BRK (bracket), ACC (accessory)", "Category master"],
     ["SUBCAT", "Article sub-category or technology", "LED, SOD, HAL, MH", "Sub-category master"],
     ["SPEC", "Defining specification", "090W (90 watt), 6M (6 metre)", "Technical specification schedule"],
     ["PO", "Purchase order reference", "PO2611", "Purchase order master — mandatory, never blank"],
     ["SEQ", "Serial number within the PO line", "000482", "System-generated, sequential, never reused"]],
    widths=[2.0, 4.4, 5.6, 4.0])

H3("Article Master Attributes")
TBL(["Attribute", "Type", "Mandatory", "Description"],
    [["Item Code", "Code", "Yes", "Generated on the pattern above; unique and permanent"],
     ["Article description", "Text", "Yes", "Full description as used in the PO and technical schedule"],
     ["Category / Sub-category", "List", "Yes", "Drives the code and the reporting hierarchy"],
     ["Technical specification", "Text / attributes", "Yes", "Wattage, lumens, IP rating, length, gauge, material as applicable"],
     ["Unit of measure", "List", "Yes", "Nos, Metre, Set, Kg, Litre. Cannot be changed once transacted"],
     ["Serialised or bulk", "Flag", "Yes", "Serialised items carry one QR per piece; bulk items carry one QR per pack or batch"],
     ["PO number and line", "Link", "Yes", "The purchase order the item was bought against"],
     ["Vendor", "Link", "Yes", "Derived from the PO"],
     ["Rate and currency", "Number", "Yes", "Taken from the PO; used for stock valuation"],
     ["Warranty period", "Number (months)", "Yes", "From the PO terms; drives warranty eligibility on failure"],
     ["Expected service life", "Number (months)", "No", "Used in failure and ageing analysis"],
     ["Re-order level and quantity", "Number", "No", "Drives replenishment alerts"],
     ["HSN / tax classification", "Code", "No", "For finance interface"],
     ["Status", "List", "Yes", "Active / Blocked / Obsolete"]],
    widths=[3.8, 2.8, 2.0, 7.4])

H2("9.4  QR Code Specification")
P("The QR code is the physical identity of the item. It is created once, at article creation against a "
  "purchase order, and is never regenerated for the same item.", align="j")
TBL(["Aspect", "Requirement"],
    [["Symbology", "QR Code Model 2, error correction level M or higher so that partial damage does not prevent reading."],
     ["Encoded payload", "Item code, PO number and line, GRN number once received, serial number, and a check value. The payload must be readable by the system offline."],
     ["Uniqueness", "Globally unique across the whole system and across all purchase orders. A code, once issued, is never reused, even after the item is scrapped."],
     ["Tamper evidence", "The check value must allow the system to reject a hand-made or duplicated label."],
     ["Label media", "Weather-resistant, UV-stable synthetic label with permanent adhesive, rated for outdoor exposure for the service life of the item."],
     ["Label content", "Human-readable item code, article description, PO number and the QR symbol, so the item remains identifiable if the symbol is damaged."],
     ["Serialised items", "One unique code per physical piece."],
     ["Bulk items", "One code per pack, batch or issue unit, carrying the quantity in the payload."],
     ["Re-printing", "Permitted for a damaged label, but the reprint carries the same code, is recorded against the item history and requires Store In-Charge authorisation."],
     ["Scanning", "Must work from the mobile camera in daylight and in low light with the torch, and at a minimum working distance suitable for a mounted luminaire."]],
    widths=[3.6, 12.4])

H2("9.5  Supporting Masters")
TBL(["Master", "Key Attributes", "Owner"],
    [["Vendor", "Vendor code, name, contact, performance rating, warranty contact, blacklist status", "Procurement"],
     ["Purchase Order", "PO number, date, vendor, line items with article, quantity, rate, delivery schedule, warranty terms", "Procurement"],
     ["Unit of Measure", "Code, description, decimal precision, conversion factors", "Store In-Charge"],
     ["Reason Codes", "Failure reasons, rejection reasons, exception reasons, adjustment reasons", "Store In-Charge"],
     ["User and Role", "User ID, name, designation, role, assigned stores and sites, approval limit, device binding", "IT Administrator"],
     ["Approval Matrix", "Transaction type, value band, approving role, escalation on delay", "PD Office"],
     ["Configuration", "Geo-fence default radius and tolerance, photo resolution, offline retention window, ageing thresholds", "IT Administrator"]],
    widths=[3.2, 9.6, 3.2])

