# =========================================================== 13 GEO RULES
H1("13.  Geo-Tagging and Evidence Rules", page_break=True)
P("Because the geo-tag is the control on which installation verification rests, its behaviour is specified "
  "here in detail rather than left to design.", align="j")

H2("13.1  Capture Requirements")
TBL(["Aspect", "Requirement"],
    [["Camera source", "Live capture through the application only. The device gallery must not be selectable."],
     ["Stamp on image", "Latitude and longitude to six decimal places, date, time with time zone, site code, item code and the officer's name, burned into the visible face of the image at capture."],
     ["Stamp placement", "A legible band at the foot of the image that does not obscure the subject of the photograph."],
     ["Data record", "The same coordinate, time and accuracy values stored as structured data alongside the image, so that validation does not depend on reading the picture."],
     ["Location accuracy", "GPS horizontal accuracy must be within the configured threshold, typically 20 metres. Below that threshold the application must warn and wait for a better fix."],
     ["Before image", "Mandatory. Must be captured before installation is recorded."],
     ["After image", "Mandatory. Must be captured after the item's QR code is scanned at the point of installation."],
     ["Image quality", "Sufficient resolution to identify the pole or point and the installed fixture, subject to a configured maximum file size for field upload."],
     ["Immutability", "Neither image nor its coordinate data may be edited, replaced or deleted after submission."],
     ["Anti-spoofing", "Mock location providers, developer location overrides and material device clock drift must be detected, the submission rejected, and the attempt logged."]],
    widths=[3.4, 12.6])

H2("13.2  Geo-Fence Validation Logic")
NUM(["The system reads the coordinates recorded with the after image.",
     "It calculates the distance between those coordinates and the coordinates of the site location the item "
     "was issued for.",
     "It compares that distance with the site's geo-fence radius plus the configured tolerance.",
     "Where the distance is within the limit, the installation is confirmed automatically and no human "
     "intervention is required.",
     "Where the distance exceeds the limit, the installation is held at PENDING VERIFICATION, the measured "
     "deviation is shown, and an exception is raised to the Lighting Supervisor.",
     "The Supervisor may either require the officer to recapture the evidence, or approve the deviation with "
     "a written justification, which is recorded permanently against the installation and reported as an "
     "exception."])

H2("13.3  Default Configuration Values")
TBL(["Parameter", "Default", "Configurable By", "Note"],
    [["Site geo-fence radius", "50 metres", "Store In-Charge / PD Office", "May be set per site; larger for road stretches, smaller for a single pole"],
     ["Geo-fence tolerance", "20 metres", "IT Administrator", "Allows for GPS drift in built-up areas"],
     ["Minimum GPS accuracy", "20 metres", "IT Administrator", "Capture is warned and delayed below this"],
     ["Maximum clock drift", "5 minutes", "IT Administrator", "Beyond this the submission is rejected"],
     ["Offline retention window", "7 days", "IT Administrator", "Maximum age of unsynchronised field transactions"],
     ["Return period after removal", "7 days", "Store In-Charge", "Beyond this the item is escalated as not returned"],
     ["Reservation validity", "5 working days", "Store In-Charge", "Unissued reservations are released automatically"],
     ["Receipt quantity tolerance", "0%", "Procurement", "Set per article or PO where contract terms allow"]],
    widths=[4.0, 2.8, 4.4, 4.8])

