     ["RK-02", "QR labels are damaged, painted over or removed in the field", "H", "M", "Weather-resistant label specification, human-readable item code printed alongside, controlled re-print process linked to the same code", "Store In-Charge"],
     ["RK-03", "Opening physical count is incomplete or inaccurate, so the system starts with wrong stock", "M", "H", "Store-by-store phasing, 100% count with audit presence, documented and explained variances rather than forced agreement", "Controller of Stores"],
     ["RK-04", "Site coordinates are captured inaccurately during survey, causing false geo-fence failures", "M", "M", "Survey quality standard, supervisor certification per zone, sample re-verification, ability to correct coordinates under approval with history retained", "Lighting Supervisor"],
     ["RK-05", "Poor connectivity delays synchronisation and makes stock position stale", "H", "M", "Full offline capture with extended retention window, synchronisation status visible to supervisors, escalation on overdue devices", "IT"],
     ["RK-06", "Staff resistance to scanning discipline; reversion to informal handovers", "M", "H", "Scan-mandatory rules with no direct-issue route, visible KPI on scan compliance, training and week-one floor support, supervisory follow-up", "PD Office"],
