# =========================================================== 23 GLOSSARY
H1("23.  Glossary", page_break=True)
TBL(["Term", "Meaning"],
    [["Article", "A type of material defined in the item master, for example a 90W LED luminaire"],
     ["Bin", "The lowest addressable physical position within a store where stock is held"],
     ["Condemnation", "The formal declaration that an item is unfit for further use and may be disposed of"],
     ["Geo-fence", "A circular boundary around a site location's coordinates within which installation evidence must fall"],
     ["Geo-tagging", "Recording the coordinates at which a photograph was taken and stamping them onto the image"],
     ["Gate Pass", "The document authorising material to leave the store premises"],
     ["GRN", "Goods Receipt Note — the document recording receipt of material into store against a purchase order"],
     ["Item Code", "The unique identifier of a specific article bought against a specific purchase order"],
     ["Issue Slip", "The document generated on requisition approval listing what is to be issued"],
     ["Lighting Officer", "The field officer who installs material at site and captures evidence"],
     ["Lighting Supervisor", "The officer who plans site work and raises requisitions"],
     ["MoSCoW", "Prioritisation method: Must have, Should have, Could have, Won't have"],
     ["Out of Order", "An installed item that has failed in service"],
     ["PO", "Purchase Order — the procurement instrument against which material is bought"],
     ["Quarantine", "A store location holding returned material pending classification"],
     ["QR Code", "A two-dimensional barcode carrying the item's identity and PO reference"],
     ["RACI", "Responsible, Accountable, Consulted, Informed"],
     ["Requisition", "The digital demand raised by a Supervisor for material for a named site"],
     ["Reservation", "Stock committed to an approved requisition and unavailable to others"],
     ["Scrap Register", "The record of condemned items written out of stock"],
     ["Serialised item", "An article tracked as individual pieces, each with its own QR code"],
     ["Site Location", "The physical point at which material is installed, defined with coordinates"],
     ["SLIMS", "Street Lighting Store, Issuance and Installation Management System"],
     ["Store Location", "The addressable position in a store, expressed as Store, Zone, Rack and Bin"],
     ["UAT", "User Acceptance Testing"],
     ["UoM", "Unit of Measure"],
     ["Warranty Claim", "A claim raised on a vendor for an item that failed within its warranty period"]],
    widths=[3.8, 12.2])
